mapper.select:
SELECT

FROM t_order
WHERE user_id = #{userId}

    AND status = #{status}

ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM t_order
WHERE user_id = #{userId}

    AND status = #{status}

mapper.update:
UPDATE t_order
SET status = #{status}
WHERE order_no = #{orderNo}

    AND status = #{oldStatus}

UPDATE t_order
SET status = 1,
    pay_time = #{payTime}
WHERE order_no = #{orderNo}
  AND status = 0

UPDATE t_order
SET status = 2,
    cancel_time = #{cancelTime}
WHERE order_no = #{orderNo}
  AND status = 0

mapper.select:
SELECT

FROM t_order
WHERE status = 0
  AND expire_time < #{deadline}
LIMIT #{limit}

SELECT COUNT(1)
FROM t_order
WHERE train_id = #{trainId}
  AND user_id = #{userId}
  AND status IN (0, 1)

SELECT COUNT(1)
FROM t_order
WHERE train_id = #{trainId}
  AND id_card = #{idCard}
  AND status IN (0, 1)
